% Validate generated bytes, source provenance and current physical parameters.
root=fileparts(fileparts(mfilename('fullpath')));
addpath(root); mixmpc_paths();
p=tinympc14_config();
families={'tinympc14_data'};
shared=tinympc14_manifest_sources();
listed={}; nv2=0;
for k=1:numel(families)
    path=fullfile(root,'build',[families{k} '.sha256']);
    assert(isfile(path),'Missing manifest; rebuild %s',families{k});
    txt=fileread(path);
    rows=regexp(txt,'([0-9a-f]{64}) \*([^\r\n]+)','tokens');
    assert(numel(rows)>=15,'Incomplete manifest');
    fam=cellfun(@(c)c{2},rows,'UniformOutput',false);
    assert(any(strcmp(fam,['build/staging/' families{k} '.h'])) && ...
        any(strcmp(fam,['build/staging/' families{k} '.c'])), ...
        'Manifest %s lacks its own generated file; rebuild',families{k});
    nv2=nv2+~isempty(strfind(txt,'# leg4-manifest v3'));
    for j=1:numel(rows)
        assert(strcmp(rows{j}{1},tinympc14_sha256(fullfile(root,rows{j}{2}))), ...
            'Data/source changed: %s; rebuild %s',rows{j}{2},families{k});
    end
    listed=[listed,cellfun(@(c)c{2},rows,'UniformOutput',false)];
    fprintf('PASS manifest %s (%d generated/source hashes)\n',families{k},numel(rows));
end
if nv2>0
    assert(nv2==numel(families),'Mixed manifest generations; rebuild all three families');
    miss=setdiff(shared,listed);
    assert(isempty(miss),'Manifests lack %d required paths (%s); rebuild', ...
        numel(miss),strjoin(miss,', '));
    fprintf('PASS manifest coverage (%d shared paths)\n',numel(shared));
else
    fprintf('NOTICE v1 manifests: full source coverage inactive until rebuild\n');
end
h=fileread(fullfile(p.STAGING_DIR,'tinympc14_data.h'));
assert(mac(h,'TINYMPC14_IFACE_VER')==3 && mac(h,'TINYMPC14_LPV_IFACE_VER')==4);
assert(mac(h,'TINYMPC14_ZOH_IFACE_VER')==1);
keys={'NX','NU','NH','RHO','TS','WHEEL_R','LEG_MASS','HALF_TRACK','ROLL_TRACK'};
vals=[p.NX,p.NU,p.NH,p.rho,p.Ts,p.R_w,p.m_l,p.R_TRK,2*p.R_TRK];
for k=1:numel(keys), assert(abs(mac(h,['TINYMPC14_' keys{k}])-vals(k))<1e-9); end
% 三笔补偿的物理量以本项目 cfg 为准, C 侧装配读的就是下面这些生成宏, 逐个核对
comp={'GRAV_FF',p.COMP.LEG_GRAV_FF; 'G',p.g; 'M_SUP',p.M_SUP; 'H_OFF',p.H_OFF; ...
      'ROLL_TRACK',p.COMP.ROLL_TRACK; 'ROLL_CLAMP',p.COMP.ROLL_CLAMP};
for k=1:size(comp,1)
    assert(abs(mac(h,['TINYMPC14_' comp{k,1}])-comp{k,2})<1e-6, ...
        'Compensation macro drift: %s',comp{k,1});
end
% 质量与腿长表与共享 Tool 同源
[tab,par]=leg_config();
assert(p.g==par.g && p.m_l==par.m_leg && p.m_b==par.m_body && p.R_TRK==par.half_track);
% MPC includes one additional 150 mm knot. Tool clamps below its 160 mm knot.
assert(isequal(p.Leg_comp(:,1),(150:10:340)'/1000) && ...
    isequal(tab(:,1),(160:10:340)'/1000) && isequal(p.Leg_data(:,1),p.Leg_comp(:,1)));
assert(all(isfinite(p.Leg_comp),'all') && all(p.Leg_comp(:,3)>0));
assert(max(abs(p.Leg_comp(2:end,2:3)-tab(:,2:3)),[],'all')<1e-7);
assert(max(abs(tinympc14_table_row(p.Leg_comp,0.150)-p.Leg_comp(1,2:3)))<1e-7, ...
    'MPC interpolation must use the 150 mm endpoint');
fprintf('PASS compensation macros and leg table match their sources\n');
assert(mac(h,'TINYMPC14_LPV_PSI_MIN')==-.3 && mac(h,'TINYMPC14_LPV_PSI_MAX')==.3);
s=regexprep(fileread(fullfile(p.STAGING_DIR,'tinympc14_data.c')),'(?s)/\*.*?\*/|//[^\r\n]*',' ');
names={'q_diag','r_diag','u_min','u_max','x_min','x_max','du_rate'};
values={p.Q_DIAG,p.R_DIAG,p.u_min,p.u_max,p.x_min,p.x_max,[1e6*ones(1,4),p.DF_RATE,p.DF_RATE]};
for k=1:numel(names)
    tok=regexp(s,['(?s)const\s+float\s+tinympc14_' names{k} '\s*\[\s*(\d+)\s*\]\s*=\s*\{(.*?)\};'],'tokens','once');
    assert(~isempty(tok),'Missing parameter %s',names{k});
    vv=str2double(regexp(tok{2},'[-+]?(?:\d+\.?\d*|\.\d+)(?:[eE][-+]?\d+)?','match'));
    assert(numel(vv)==numel(values{k}) && max(abs(vv-values{k}))<1e-5*max(1,max(abs(values{k}))));
end
% Rebuild the single-point cache from current sources and compare with the
% staged bytes so a hand-edited or stale table cannot be blessed by
% rewriting the manifest alone.
sched=tinympc14_sched_pt(p,p.sym7.sched_l,0,p.sym7.sched_psi);
[xbar,~,eq]=tinympc14_equilibrium(p,p.sym7.sw_fused,sched);
sched.eq=eq.eq; sched.psi_l=xbar(5); sched.psi_r=xbar(7);
[A,B,f]=tinympc14_fused_ab(p,p.sym7.sw_fused,sched);
[Ad,Bd,fd]=tinympc14_zoh_ab(A,B,f,p.Ts);
Q=diag(p.Q_DIAG); Rm=diag(p.R_DIAG);
[Kinf,Pinf]=tinympc14_dare_gain(Ad,Bd,Q,Rm,p.rho,p.NX,p.NU);
QuuInv=inv(Rm+p.rho*eye(p.NU)+Bd'*Pinf*Bd);
AmBKt=(Ad-Bd*Kinf)';
ref=[rm(Ad);rm(Bd);fd(:);rm(Kinf);rm(Pinf);rm(QuuInv);rm(AmBKt)];
tok=regexp(s,'(?s)tinympc14_model\s*=\s*\{(.*?)\n\};','tokens','once');
assert(~isempty(tok),'Cannot parse staged model initializer');
stg=str2double(regexp(tok{1},'[-+]?(?:\d+\.?\d*|\.\d+)(?:[eE][-+]?\d+)?','match')).';
assert(numel(stg)==numel(ref),'Staged model has %d coefficients, expected %d; rebuild', ...
    numel(stg),numel(ref));
cnt=[196 84 14 84 196 36 196];
assert(isempty(find_bad(stg,ref,cnt,1e-5)), ...
    'Single-point table not reproducible from sources; rebuild s03');
fprintf('PASS single-point table re-derived from sources (max rel %.2e)\n',worst(stg,ref,cnt));
% Bind the terminal cache used by MATLAB to the Coder input recorded in the
% staged header. Numerical MATLAB/C parity is checked by the host vectors.
cache_file=fullfile(root,'build','tinympc14_lpv_psi_cache.mat');
digest=regexp(h,'#define TINYMPC14_LPV_CACHE_SHA256 "([0-9a-f]{64})"','tokens','once');
assert(~isempty(digest) && strcmp(digest{1},tinympc14_sha256(cache_file)), ...
    'Terminal cache differs from generated C input; rebuild s04d');
S=load(cache_file,'table','weights','report');
assert(isequal(S.weights.Q,p.Q_DIAG) && isequal(S.weights.R,p.R_DIAG) && S.weights.rho==p.rho);
assert(mac(h,'TINYMPC14_LPV_TERMINAL_RANK')==size(S.table.basis,1));
assert(S.report.min_terminal_eig>0 && S.report.max_radius<1 ...
    && S.report.max_terminal_error<.03 && S.report.max_gain_error<.03 ...
    && max(S.report.max_zoh_error)<1e-8);
fprintf('PASS terminal cache matches generated C input and current weights\n');
fz=zoh_from_c(fileread(fullfile(p.STAGING_DIR,'tinympc14_data.c')));
Z=load(fullfile(root,'build','tinympc14_zoh_cache.mat'),'fz');
assert(isequal(size(fz),size(Z.fz)),'ZOH cache shape mismatch; rebuild s07_tinympc14_zoh_data');
atolZ=1e-9*max(1,max(abs(Z.fz(:))));
assert(~any(abs(fz-Z.fz)>max(1e-5*abs(Z.fz),atolZ),'all'), ...
    'ZOH mat cache differs from staged coefficients; rebuild');
fprintf('PASS ZOH coefficients match staging/tinympc14_data.c (max rel %.2e)\n', ...
    max(max(abs(fz-Z.fz)./max(abs(Z.fz),atolZ))));
clear tinympc14_lpv_eval tinympc14_zoh_apply;
mdl=tinympc14_lpv_eval(p,.27,.27,0);
assert(all(isfinite([mdl.Ad(:);mdl.Bd(:);mdl.fd(:);mdl.Pinf(:)])));
assert(min(eig((mdl.Pinf+mdl.Pinf')/2-p.rho*eye(p.NX)))>0,'Terminal cost not positive definite');
assert(max(abs(eig(mdl.Ad-mdl.Bd*mdl.Kinf)))<1);
fprintf('S7 static check: PASS\n');
function vv=mac(s,name)
t=regexp(s,['#define\s+' name '\s+([-+0-9.eE]+)f?'],'tokens','once');
assert(~isempty(t),'Missing macro %s',name); vv=str2double(t{1});
end
function fz=zoh_from_c(s)
s=regexprep(s,'(?s)/\*.*?\*/|//[^\r\n]*',' ');
tok=regexp(s,'(?s)tinympc14_fz\s*\[\s*TINYMPC14_ZOH_NF\s*\]\s*\[\s*TINYMPC14_ZOH_NX\s*\]\s*=\s*\{(.*?)\n\};','tokens','once');
assert(~isempty(tok),'Cannot parse ZOH table');
v=str2double(regexp(tok{1},'[-+]?(?:\d+\.?\d*|\.\d+)(?:[eE][-+]?\d+)?','match'));
assert(numel(v)==14*4,'ZOH table has %d coefficients, expected %d',numel(v),14*4);
fz=reshape(v,14,4).';
end
function bad=find_bad(got,ref,cnt,rtol)
bad=zeros(1,0); off=0;
for b=1:numel(cnt)
    ii=(off+1):(off+cnt(b)); off=off+cnt(b);
    g=got(ii); r=ref(ii);
    atol=1e-9*max(1,max(abs(r)));
    bad=[bad,ii(abs(g-r)>max(rtol*abs(r),atol))];
end
end
function w=worst(got,ref,cnt)
w=0; off=0;
for b=1:numel(cnt)
    ii=(off+1):(off+cnt(b)); off=off+cnt(b);
    d=abs(got(ii)-ref(ii))./max(abs(ref(ii)),1e-9*max(1,max(abs(ref(ii)))));
    w=max(w,max(d));
end
end
function v=rm(M)
v=reshape(M.',[],1);
end
